{
  "evidence": [
    {
      "ref_id": "p001",
      "group_ids": [
        "P2"
      ],
      "quote": "公司依据《员工手册》建立员工申诉机制,员工在权益受损时可通过指定渠道提交书面申诉材料,公司将在收到申诉后迅速启动调查程序,秉持严谨、公正的态度处理投诉事宜,并 及时向管理层同步调查进展与结果。公司注重隐私保护,对投诉人的个人信息严格保密,确保投诉人隐私安全,并保证处理结果及时反馈至员工。",
      "kind": "mechanism",
      "period": "2025年度",
      "scope": "未明确",
      "relevance": "披露了员工申诉机制，包括提交渠道、调查程序及反馈安排，符合工资差错查询或薪酬申诉渠道的广义定义（权益受损申诉）。"
    },
    {
      "ref_id": "p003",
      "group_ids": [
        "P2"
      ],
      "quote": "公司制定并完善《薪酬福利管理制度》,加强薪酬合规管理,持续提供津贴,并优化长期激 励制度。 2025 年,公司开展员工薪酬水平市场调研工作,旨在对标行业标准,科学评估公司薪酬 竞争力与内部公平性,为后续的薪酬调整与人工成本预算编制提供数据支撑。同时,公司持续为 员工提供多种津贴,涵盖异地工作派遣补贴、海外艰苦项目补贴及岗位津贴等类别。",
      "kind": "policy",
      "period": "2025年度",
      "scope": "未明确",
      "relevance": "提及《薪酬福利管理制度》及薪酬合规管理，虽未详述具体核算复核流程，但确立了薪酬管理的制度基础。"
    },
    {
      "ref_id": "p009",
      "group_ids": [
        "P3"
      ],
      "quote": "董事、高级管理人员薪酬确定依 据 | 公司董事会薪酬与考核委员会根据公司经营成果及所处行业 与地区的薪酬水平,结合相关岗位的重要性、职责范围以及个 人绩效考核情况,制定薪酬方案,报公司董事会或股东大会审 议。\n董事和高级管理人员薪酬的实际 支付情况 | 公司董事和高级管理人员的报酬已根据相关规定支付。\n报告期末全体董事和高级管理人 员实际获得薪酬的考核依据和完 成情况 | 报告期内,执行董事不领取董事薪酬,非执行董事及独立非执 行董事领取固定董事薪酬,不适用考核程序。 公司高级管理人员薪酬考核依据《公司章程》及有关制度,结 合年度经营目标完成度、个人履职表现、行业薪酬水平等维度 综合评定;报告期内相关人员均完成对应考核指标。",
      "kind": "action",
      "period": "2025年度",
      "scope": "董事、高级管理人员",
      "relevance": "披露了董监高薪酬的决策程序、审议情况及实际支付状态，属于针对特定层级员工的薪酬支付监测/审查事实。"
    },
    {
      "ref_id": "p004",
      "group_ids": [
        "T5"
      ],
      "quote": "通过优化审批流程,实现考勤异常人次、加班人数及时长合理化。",
      "kind": "result",
      "period": "2025年度",
      "scope": "未明确",
      "relevance": "披露了当期通过优化流程实现的工时管理结果（考勤异常、加班时长合理化），属于实际执行或纠正结果。"
    },
    {
      "ref_id": "p008",
      "group_ids": [
        "D5"
      ],
      "quote": "依托于完善的内部举报与调查机制,公司明确要求全体员工在发现雇佣童工、强制劳工、 歧视或骚扰等违规行为时,须通过人力资源部或直属主管等指定渠道及时上报。公司保 证调查全程遵循公正、透明的程序,并严格保密举报人信息,切实维护员工权益与组织 公信力。",
      "kind": "mechanism",
      "period": "2025年度",
      "scope": "全体员工",
      "relevance": "披露了针对歧视或骚扰等违规行为的内部举报与调查机制，包含上报渠道和调查程序，符合责任追究与纠正补救中的机制要求。"
    }
  ]
}
